use vstd::prelude::*;

verus! {
    // Specification for the copy function
    fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
        requires
            // The input vector must be finite and well-formed
            arr.len() < 0x1_0000_0000, // Ensure the length is less than a large number to avoid overflow
        ensures
            // The result vector must have the same length as the input vector
            result.len() == arr.len() &&
            // For every valid index, the elements must be equal
            forall|i: nat| (i < arr.len() as nat) ==> (result[i] == arr[i]),
        decreases
            arr.len() // Decrease clause to ensure termination
    {
        let mut result: Vec<i8> = Vec::with_capacity(arr.len());
        result.resize(arr.len(), 0); // Initialize the result vector with the same length

        let mut idx: nat = 0; // Initialize index
        while idx < arr.len() as nat
            invariant
                idx <= arr.len() as nat,
                result.len() == arr.len(),
                forall|i: nat| (i < idx) ==> (result[i] == arr[i]),
            decreases
                arr.len() as nat - idx, // Ensure the loop decreases
        {
            // Copy the element from arr to result
            result[idx] = arr[idx as usize];
            idx = idx + 1; // Increment the index
        }
        result
    }
}

